<?php defined('SYSPATH') or die('No direct script access.');
class Service_Erp409_Costing
{
    protected static $_instance;
    public static function instance(){ return self::$_instance ?: self::$_instance=new self; }

    public function orders($limit=50)
    {
        return DB::query(Database::SELECT,"SELECT o.id,o.uuid,o.number,o.title,o.status,o.qty,o.qty_done,o.uom_code,
            c.id calculation_id,c.version,c.status calculation_status,c.actual_total,c.planned_total,c.actual_unit_cost,c.calculated_at
            FROM erp_402_orders o LEFT JOIN LATERAL(SELECT * FROM erp_409_calculations x WHERE x.order_id=o.id ORDER BY version DESC LIMIT 1)c ON true
            WHERE o.status<>'cancelled' ORDER BY o.id DESC LIMIT :limit")->param(':limit',max(1,min(200,(int)$limit)))->execute()->as_array();
    }
    public function get($id)
    {
        $row=DB::query(Database::SELECT,"SELECT * FROM erp_409_calculations WHERE ".(ctype_digit((string)$id)?'id=:id':'uuid=CAST(:id AS uuid)'))->param(':id',$id)->execute()->current();
        if(!$row) throw new Kohana_Exception('Калькуляция не найдена');
        $row['warnings']=json_decode((string)$row['warnings'],TRUE)?:array();
        $row['lines']=DB::select()->from('erp_409_lines')->where('calculation_id','=',(int)$row['id'])->order_by('side')->order_by('category')->order_by('id')->execute()->as_array();
        return $row;
    }
    public function history($order_id){ return DB::select()->from('erp_409_calculations')->where('order_id','=',(int)$order_id)->order_by('version','DESC')->execute()->as_array(); }

    public function calculate($order_id,$actor_id=NULL)
    {
        $order=DB::select()->from('erp_402_orders')->where('id','=',(int)$order_id)->execute()->current();
        if(!$order) throw new Kohana_Exception('Производственный заказ не найден');
        $db=Database::instance();$db->begin();
        try {
            DB::query(Database::SELECT,'SELECT id FROM erp_402_orders WHERE id=:id FOR UPDATE')->param(':id',(int)$order_id)->execute();
            $version=(int)DB::query(Database::SELECT,'SELECT COALESCE(MAX(version),0)+1 version FROM erp_409_calculations WHERE order_id=:id')->param(':id',(int)$order_id)->execute()->get('version');
            $insert=DB::query(Database::SELECT,"INSERT INTO erp_409_calculations(order_id,order_number,order_title,version,output_qty,calculated_by) VALUES(:oid,:number,:title,:version,:qty,:actor) RETURNING id")
                ->parameters(array(':oid'=>(int)$order_id,':number'=>$order['number'],':title'=>$order['title'],':version'=>$version,':qty'=>(float)$order['qty_done'],':actor'=>$actor_id?:NULL))->execute()->current();
            $calc_id=(int)$insert['id'];$totals=array('planned_material'=>0,'planned_labor'=>0,'planned_machine'=>0,'actual_material'=>0,'actual_labor'=>0,'actual_machine'=>0);$warnings=array();
            $items=DB::select()->from('erp_402_order_items')->where('order_id','=',(int)$order_id)->order_by('line_no')->execute()->as_array();
            foreach($items as $item){$rate=$this->rate((int)$item['item_id']);if(!$rate['found'])$warnings[]='Нет закупочной ставки для '.$item['name'];$amount=round((float)$item['qty_total']*$rate['rate'],2);$totals['planned_material']+=$amount;$this->line($calc_id,'plan','material',$item['name'],(float)$item['qty_total'],$item['uom_code'],$rate['rate'],$amount,'procurement.latest_price',$rate['ref'],array('item_id'=>$item['item_id'],'source_type'=>'erp402_order_item','source_id'=>$item['id']));}
            $moves=DB::query(Database::SELECT,"SELECT m.*,COALESCE(i.name,'Номенклатура #'||m.item_id) item_name FROM erp_401_movements m LEFT JOIN erp_227_objects i ON i.id=m.item_id WHERE m.doc_type='erp402_order' AND m.doc_id=:id AND m.type='issue' AND m.status='posted' ORDER BY m.id")->param(':id',(int)$order_id)->execute()->as_array();
            foreach($moves as $move){$rate=$this->rate((int)$move['item_id'],(string)$move['performed_at']);if(!$rate['found'])$warnings[]='Нет ставки на дату движения #'.$move['id'];$amount=round((float)$move['qty']*$rate['rate'],2);$totals['actual_material']+=$amount;$this->line($calc_id,'actual','material',$move['item_name'],(float)$move['qty'],$move['uom_code'],$rate['rate'],$amount,'procurement.price_as_of',$rate['ref'],array('item_id'=>$move['item_id'],'source_type'=>'erp401_movement','source_id'=>$move['id']));}
            $operations=DB::query(Database::SELECT,"SELECT o.*,w.code center_code,w.name center_name,w.cost_per_hour FROM erp_408_operations o LEFT JOIN erp_408_work_centers w ON w.id=o.work_center_id WHERE o.order_id=:id AND o.status<>'cancelled' ORDER BY o.op_no")->param(':id',(int)$order_id)->execute()->as_array();
            foreach($operations as $op){$planned_labor=(float)$op['norm_cost'];$actual_labor=(float)$op['planned_hours']>0?round($planned_labor*((float)$op['worked_sec']/3600)/(float)$op['planned_hours'],2):0;$rate=(float)$op['cost_per_hour'];$plan_machine=round((float)$op['planned_hours']*$rate,2);$actual_hours=(float)$op['worked_sec']/3600;$actual_machine=round($actual_hours*$rate,2);$totals['planned_labor']+=$planned_labor;$totals['actual_labor']+=$actual_labor;$totals['planned_machine']+=$plan_machine;$totals['actual_machine']+=$actual_machine;$ref=trim((string)$op['center_code'].' '.(string)$op['center_name']);$base=array('operation_id'=>$op['id'],'source_type'=>'erp408_operation','source_id'=>$op['id']);$this->line($calc_id,'plan','labor',$op['name'],1,'operation',$planned_labor,$planned_labor,'erp408.operation.norm_cost','Операция #'.$op['id'],$base);$this->line($calc_id,'actual','labor',$op['name'],$actual_hours,'h',$op['planned_hours']>0?$planned_labor/(float)$op['planned_hours']:0,$actual_labor,'norm_cost.prorated_by_actual_time','Операция #'.$op['id'],$base);$this->line($calc_id,'plan','machine',$op['name'],(float)$op['planned_hours'],'h',$rate,$plan_machine,'erp408.work_center.cost_per_hour',$ref,$base);$this->line($calc_id,'actual','machine',$op['name'],$actual_hours,'h',$rate,$actual_machine,'erp408.work_center.cost_per_hour',$ref,$base);}
            $planned=$totals['planned_material']+$totals['planned_labor']+$totals['planned_machine'];$actual=$totals['actual_material']+$totals['actual_labor']+$totals['actual_machine'];$ok=0;$scrap=0;foreach($operations as $op){$ok+=(float)$op['qty_ok'];$scrap+=(float)$op['qty_scrap'];}$scrap_loss=($ok+$scrap)>0?round($actual*$scrap/($ok+$scrap),2):0;if($scrap>0)$this->line($calc_id,'actual','scrap','Аналитическая доля брака',$scrap,$order['uom_code'],($ok+$scrap)>0?$actual/($ok+$scrap):0,$scrap_loss,'yield_loss_allocation','Не добавляется повторно в итог',array('source_type'=>'erp408_operations','included_in_total'=>FALSE));
            $qty=(float)$order['qty_done'];DB::query(Database::UPDATE,"UPDATE erp_409_calculations SET planned_material=:pm,planned_labor=:pl,planned_machine=:pc,actual_material=:am,actual_labor=:al,actual_machine=:ac,scrap_loss=:scrap,planned_total=:pt,actual_total=:at,planned_unit_cost=:pu,actual_unit_cost=:au,warnings=CAST(:warnings AS jsonb) WHERE id=:id")
                ->parameters(array(':pm'=>$totals['planned_material'],':pl'=>$totals['planned_labor'],':pc'=>$totals['planned_machine'],':am'=>$totals['actual_material'],':al'=>$totals['actual_labor'],':ac'=>$totals['actual_machine'],':scrap'=>$scrap_loss,':pt'=>$planned,':at'=>$actual,':pu'=>(float)$order['qty']>0?$planned/(float)$order['qty']:NULL,':au'=>$qty>0?$actual/$qty:NULL,':warnings'=>json_encode(array_values(array_unique($warnings)),JSON_UNESCAPED_UNICODE),':id'=>$calc_id))->execute();
            $db->commit();$result=$this->get($calc_id);$this->journal($result,'calculated',array(),array('version'=>$result['version'],'planned_total'=>$result['planned_total'],'actual_total'=>$result['actual_total']),$actor_id);return $result;
        } catch(Exception $e){$db->rollback();throw $e;}
    }
    public function approve($id,$actor_id=NULL){$calc=$this->get($id);if($calc['status']==='approved')return $calc;DB::query(Database::UPDATE,"UPDATE erp_409_calculations SET status='approved',approved_at=CURRENT_TIMESTAMP,approved_by=:actor WHERE id=:id")->parameters(array(':actor'=>$actor_id?:NULL,':id'=>(int)$calc['id']))->execute();$result=$this->get($calc['id']);$this->journal($result,'approved',array('status'=>'draft'),array('status'=>'approved'),$actor_id);if(class_exists('Service_Erp208_EventBus')){try{Event::fire('erp409.costing.approved',array('calculation_id'=>(int)$result['id'],'calculation_uuid'=>(string)$result['uuid'],'order_id'=>(int)$result['order_id'],'version'=>(int)$result['version'],'actual_total'=>(float)$result['actual_total'],'currency'=>(string)$result['currency']));}catch(Exception $e){Kohana::$log->add(Log::WARNING,'erp409: событие утверждения недоступно — :error',array(':error'=>$e->getMessage()));}}return $result;}
    protected function rate($item_id,$at=NULL){if(!$item_id)return array('found'=>FALSE,'rate'=>0,'ref'=>'Номенклатура не выбрана');$sql="SELECT id,price,qty,currency,dated_at,source FROM erp_403_prices WHERE item_id=:item AND currency='RUB'".($at?' AND dated_at<=CAST(:at AS timestamp)':'')." ORDER BY dated_at DESC,id DESC LIMIT 1";$q=DB::query(Database::SELECT,$sql)->param(':item',$item_id);if($at)$q->param(':at',$at);$r=$q->execute()->current();if(!$r)return array('found'=>FALSE,'rate'=>0,'ref'=>'Нет цены');$rate=(float)$r['qty']>0?(float)$r['price']/(float)$r['qty']:(float)$r['price'];return array('found'=>TRUE,'rate'=>$rate,'ref'=>'Цена #'.$r['id'].' · '.$r['source'].' · '.$r['dated_at']);}
    protected function line($calc,$side,$category,$label,$qty,$uom,$rate,$amount,$rate_source,$ref,array $x){DB::query(Database::INSERT,"INSERT INTO erp_409_lines(calculation_id,side,category,label,item_id,operation_id,source_type,source_id,qty,uom_code,rate,amount,rate_source,source_ref,included_in_total,explanation) VALUES(:calc,:side,:category,:label,:item,:operation,:stype,:sid,:qty,:uom,:rate,:amount,:rs,:ref,:included,CAST(:explanation AS jsonb))")->parameters(array(':calc'=>$calc,':side'=>$side,':category'=>$category,':label'=>$label,':item'=>Arr::get($x,'item_id'),':operation'=>Arr::get($x,'operation_id'),':stype'=>$x['source_type'],':sid'=>Arr::get($x,'source_id'),':qty'=>$qty,':uom'=>$uom,':rate'=>$rate,':amount'=>$amount,':rs'=>$rate_source,':ref'=>$ref,':included'=>Arr::get($x,'included_in_total',TRUE),':explanation'=>json_encode(array('formula'=>'quantity × rate','rate_source'=>$rate_source,'source_ref'=>$ref),JSON_UNESCAPED_UNICODE)))->execute();}
    protected function journal(array $calc,$action,array $before,array $after,$actor_id){if(!class_exists('Service_Erp119_Journal'))return;try{$options=array('module'=>'erp409','entity_label'=>$calc['order_number'].' v'.$calc['version'],'message'=>'Версия объяснимой себестоимости');if($actor_id)$options['actor_id']=(int)$actor_id;Service_Erp119_Journal::instance()->change('costing',(string)$calc['uuid'],$action,$before,$after,$options);}catch(Exception $e){Kohana::$log->add(Log::WARNING,'erp409: журнал недоступен — :error',array(':error'=>$e->getMessage()));}}
}
